  QuoteEntry(
    id: 'gracian_oraculo_55',
    text: {
      'en': 'Be someone who can wait. It shows a great heart, with room for patience. Never rush, never get carried away.',
      'de': 'Sei ein Mensch, der warten kann. Das zeugt von einem großen Herzen voller Geduld. Nie hasten, nie sich hinreißen lassen.',
